class Solution {
public:
    bool isPossible(vector<int>& target) {
        int n = target.size();
        if (n == 1) return target[0] == 1;

        long long sum = 0;
        priority_queue<long long> pq;
        for (int x : target) {
            sum += x;
            pq.push(x);
        }

        while (pq.top() > 1) {
            long long mx = pq.top();
            pq.pop();
            long long rest = sum - mx;
            if (rest <= 0 || mx <= rest) return false;
            long long new_val = mx % rest;
            if (new_val == 0) new_val = rest;
            sum = sum - mx + new_val;
            pq.push(new_val);
        }
        return true;
    }
};
